sksl:
uniform shader image;
uniform float2 size;
uniform float4 screen;
uniform float time;
uniform float2 center;
uniform float strength;
uniform float radius;
uniform float reach;

half4 main(float2 coord) {
    float2 c = center * size;
    float2 d = coord - c;
    float r = max(radius * (reach > 0.5 ? min(screen.z, screen.w) : min(size.x, size.y)), 0.0001);
    float t = clamp(1.0 - length(d) / r, 0.0, 1.0);
    float a = reach > 0.5 ? -50.265482 * strength * t * t : -48.0 * strength * t;
    float cs = cos(a);
    float sn = sin(a);
    return image.eval(c + float2(cs * d.x - sn * d.y, sn * d.x + cs * d.y));
}
